using System.Text;
using Guardrails.Core.Execution;
using Guardrails.Core.Model;

namespace Guardrails.Cli.Ui;

/// <summary>
/// A decorator <see cref="IRunObserver"/> that keeps a plan's <c>diagram.html</c> reflecting the
/// run's live progress (issue #219), mirroring <see cref="OnTheFlyLogSiteObserver"/>'s shape. It
/// WRAPS the real observer, forwards every event verbatim, and after certain events re-renders the
/// diagram from an in-memory per-node status map via <see cref="HtmlDiagramRenderer.Render"/>'s
/// optional <c>nodeStatuses</c> parameter (02-implement-diagram-status-overlay-renderer):
/// <list type="bullet">
///   <item>On <see cref="TaskStarting"/> the task's CONTAINER node flips to <c>"running"</c>
///     (coarse — per-check granularity for a task's own checks is unnecessary here since they have
///     not run yet; it is driven by <see cref="GuardrailFinished"/> instead).</item>
///   <item>On <see cref="GuardrailFinished"/> only the SPECIFIC preflight/guardrail leaf node that
///     just finished flips to <c>"passed"</c>/<c>"failed"</c> — never the whole task container.</item>
///   <item>On <see cref="TaskFinished"/> the task's container flips to its settled status
///     (<c>"passed"</c>/<c>"failed"</c>/<c>"needs-human"</c>, mapped from <see cref="TaskOutcome"/>).</item>
/// </list>
///
/// <para>
/// <b>Design choice (this task's either/or):</b> the Mermaid source, its source hash, and the
/// task-folder-targets map are threaded straight through the constructor — the same values the
/// caller (mirroring <c>GraphCommand</c>'s <c>MermaidRenderer.RenderInteractive</c> /
/// <c>TaskFolderTargets</c> calls) already computes from the live <c>PlanDefinition</c> — rather
/// than re-parsing them back out of the already-written <c>diagram.html</c>'s embedded
/// <c>&lt;script&gt;</c> tags. Threading is simpler and avoids a fragile round-trip through HTML/JSON
/// that would break the moment the embedded markup's shape changes for an unrelated reason.
/// </para>
///
/// <para>
/// <b>Node-id scheme.</b> <see cref="MermaidRenderer"/>'s injective task-id → node-id-base
/// allocation (collision-safe sanitize + <c>_2</c>/<c>_3</c>… disambiguation) is <c>private</c>, so
/// this class reproduces it character-for-character (see <see cref="AllocateNodeIdBases"/> /
/// <see cref="Sanitize"/>) to compute the SAME container id (<c>task_&lt;base&gt;</c>) and leaf ids
/// (<c>task_&lt;base&gt;_pf_&lt;n&gt;</c> / <c>task_&lt;base&gt;_gr_&lt;n&gt;</c>, <c>n</c> = the
/// check's ordinal position when its task's <see cref="TaskNode.Preflights"/>/
/// <see cref="TaskNode.Guardrails"/> are sorted ordinal by <see cref="GuardrailDefinition.Name"/>,
/// exactly as <c>MermaidRenderer.AppendCheckNodes</c> emits them) that <c>diagram.html</c> already
/// embeds, so a status badge lands on the right SVG node.
/// </para>
///
/// <para>
/// This decorator's own status map is the only shared mutable state, and M4 worker threads may call
/// in concurrently, so all access to it — and the write that projects from it — is serialised under
/// one lock, mirroring <see cref="OnTheFlyLogSiteObserver"/>. Renders are best-effort: a render
/// failure (e.g. a transient file lock, or a bad output path) is swallowed so a UX nicety never
/// flips a task's outcome or aborts the run.
/// </para>
///
/// <para>
/// <b>MINIMAL STUB (this task authors failing tests only).</b> <see cref="WriteDiagram"/> always
/// throws <see cref="NotImplementedException"/> — the real re-render (calling
/// <see cref="HtmlDiagramRenderer.Render"/> and writing it to <c>diagram.html</c>) is
/// <c>04-implement-diagram-observer</c>'s job. Every status-map/node-id bookkeeping method above is
/// real (not stubbed) so the authored tests encode the CORRECT expected node ids/statuses and turn
/// green the moment <see cref="WriteDiagram"/> is implemented for real.
/// </para>
/// </summary>
public sealed class OnTheFlyDiagramObserver : IRunObserver
{
    private readonly IRunObserver _inner;
    private readonly string _diagramHtmlPath;
    private readonly string _mermaidSource;
    private readonly string _sourceHash;
    private readonly IReadOnlyDictionary<string, string> _taskFolderTargets;

    private readonly IReadOnlyDictionary<string, TaskNode> _tasksById;
    private readonly IReadOnlyDictionary<string, string> _nodeIdBaseByTaskId;

    // Per-node status word (container + leaf check ids). Mutated and projected under one lock —
    // events may arrive from concurrent M4 workers, and the render reads the whole map, so the two
    // must not race (mirrors OnTheFlyLogSiteObserver's _gate).
    private readonly object _gate = new();
    private readonly Dictionary<string, string> _statusByNode = new(StringComparer.Ordinal);

    /// <param name="inner">The real observer every event is forwarded to (live or console).</param>
    /// <param name="tasks">The plan's tasks — used to resolve container/leaf node ids.</param>
    /// <param name="diagramHtmlPath">The plan's <c>diagram.html</c> path, re-rendered in place.</param>
    /// <param name="mermaidSource">
    /// The interactive Mermaid source (<c>MermaidRenderer.RenderInteractive</c>'s output) to re-embed
    /// on every re-render — identical to what <c>diagram.html</c> already carries.
    /// </param>
    /// <param name="sourceHash">The plan's <c>source-sha256</c> provenance stamp.</param>
    /// <param name="taskFolderTargets">
    /// The task-container-id → plan-relative-folder-path map (<c>MermaidRenderer.TaskFolderTargets</c>)
    /// the title-band click overlay needs, re-embedded unchanged on every re-render.
    /// </param>
    public OnTheFlyDiagramObserver(
        IRunObserver inner,
        IReadOnlyList<TaskNode> tasks,
        string diagramHtmlPath,
        string mermaidSource,
        string sourceHash,
        IReadOnlyDictionary<string, string> taskFolderTargets)
    {
        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
        ArgumentNullException.ThrowIfNull(tasks);
        _diagramHtmlPath = diagramHtmlPath ?? throw new ArgumentNullException(nameof(diagramHtmlPath));
        _mermaidSource = mermaidSource ?? throw new ArgumentNullException(nameof(mermaidSource));
        _sourceHash = sourceHash ?? throw new ArgumentNullException(nameof(sourceHash));
        _taskFolderTargets = taskFolderTargets ?? throw new ArgumentNullException(nameof(taskFolderTargets));

        _tasksById = tasks.ToDictionary(t => t.Id, StringComparer.Ordinal);
        _nodeIdBaseByTaskId = AllocateNodeIdBases(tasks);
    }

    public void TaskStarting(TaskNode task)
    {
        _inner.TaskStarting(task);
        SetStatus(ContainerId(task), "running");
        Render();
    }

    public void AttemptStarting(TaskNode task, int attempt, int budget) =>
        _inner.AttemptStarting(task, attempt, budget);

    public void GuardrailFinished(TaskNode task, GuardrailResult result)
    {
        _inner.GuardrailFinished(task, result);

        string? nodeId = ResolveCheckNodeId(task, result.Name);
        if (nodeId is not null)
        {
            SetStatus(nodeId, result.Passed ? "passed" : "failed");
        }

        Render();
    }

    public void TaskFinished(TaskResult result)
    {
        _inner.TaskFinished(result);

        if (_tasksById.TryGetValue(result.TaskId, out TaskNode? task))
        {
            SetStatus(ContainerId(task), SettledStatusWord(result.Outcome));
        }

        Render();
    }

    public void PlanHashMismatch(string previousPlanHash) => _inner.PlanHashMismatch(previousPlanHash);

    public void ParallelismClampedNoProvider(int requested) => _inner.ParallelismClampedNoProvider(requested);

    public void CleanupFailed(string owner, Exception error) => _inner.CleanupFailed(owner, error);

    public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
        _inner.PromptPaused(task, reason, backoff, pauseCount);

    // --- status-map bookkeeping -------------------------------------------------------------

    private void SetStatus(string nodeId, string status)
    {
        lock (_gate)
        {
            _statusByNode[nodeId] = status;
        }
    }

    /// <summary>
    /// Rewrite <c>diagram.html</c> from the current status map. Holds the lock for the whole render
    /// so the status snapshot is internally consistent. Best-effort via <see cref="TryRender"/>.
    /// </summary>
    private void Render()
    {
        lock (_gate)
        {
            var snapshot = new Dictionary<string, string>(_statusByNode, StringComparer.Ordinal);
            TryRender(() => WriteDiagram(snapshot));
        }
    }

    /// <summary>
    /// MINIMAL STUB (issue #219 wiring): the real re-render — call
    /// <see cref="HtmlDiagramRenderer.Render"/> with <paramref name="nodeStatuses"/> and atomically
    /// write the result to <see cref="_diagramHtmlPath"/> — is <c>04-implement-diagram-observer</c>'s
    /// job. Deliberately throws so every render-triggering test authored against this class is a
    /// TDD red until that task lands. References every constructor-only field so none is flagged
    /// unused under this repo's TreatWarningsAsErrors policy.
    /// </summary>
    private void WriteDiagram(IReadOnlyDictionary<string, string> nodeStatuses)
    {
        throw new NotImplementedException(
            "OnTheFlyDiagramObserver.WriteDiagram is a stub (04-implement-diagram-observer): "
            + $"path={_diagramHtmlPath}, sourceHash={_sourceHash}, "
            + $"mermaidSourceLength={_mermaidSource.Length}, "
            + $"taskFolderTargetsCount={_taskFolderTargets.Count}, "
            + $"nodeStatusesCount={nodeStatuses.Count}.");
    }

    /// <summary>
    /// Run a render action, swallowing IO failures: the on-the-fly diagram is a UX nicety and must
    /// never flip a task's outcome or abort the run. A transient lock/torn-read is retried by the
    /// next event. Mirrors <see cref="OnTheFlyLogSiteObserver"/>'s identical helper exactly.
    /// </summary>
    private static void TryRender(Action render)
    {
        try
        {
            render();
        }
        catch (IOException)
        {
            // best-effort — the next event re-renders
        }
        catch (UnauthorizedAccessException)
        {
            // best-effort — never let a diagram-path permission hiccup abort the run
        }
    }

    // --- node-id resolution -------------------------------------------------------------------

    private string ContainerId(TaskNode task) => $"task_{_nodeIdBaseByTaskId[task.Id]}";

    /// <summary>
    /// Resolve a finished check's specific leaf node id: <paramref name="checkName"/> is looked up
    /// first against <paramref name="task"/>'s <see cref="TaskNode.Preflights"/>, then its
    /// <see cref="TaskNode.Guardrails"/> (both sorted ordinal by name, mirroring
    /// <c>MermaidRenderer.AppendCheckNodes</c>'s emission order) — so a task-level preflight and a
    /// guardrail are never confused even if their names happened to collide. Returns null
    /// (defensive — never set a status for an unrecognized check) when no check matches.
    /// </summary>
    private string? ResolveCheckNodeId(TaskNode task, string checkName)
    {
        string @base = _nodeIdBaseByTaskId[task.Id];

        int pfIndex = IndexOfByName(task.Preflights, checkName);
        if (pfIndex >= 0)
        {
            return $"task_{@base}_pf_{pfIndex}";
        }

        int grIndex = IndexOfByName(task.Guardrails, checkName);
        return grIndex >= 0 ? $"task_{@base}_gr_{grIndex}" : null;
    }

    private static int IndexOfByName(IReadOnlyList<GuardrailDefinition> checks, string name)
    {
        List<GuardrailDefinition> sorted = checks.OrderBy(c => c.Name, StringComparer.Ordinal).ToList();
        for (int i = 0; i < sorted.Count; i++)
        {
            if (string.Equals(sorted[i].Name, name, StringComparison.Ordinal))
            {
                return i;
            }
        }

        return -1;
    }

    /// <summary>
    /// Map a finished task's outcome to one of the diagram's three settled status words — the
    /// live/pending words ("running"/"pending") never apply here since the task has already
    /// finished. <see cref="TaskOutcome.Succeeded"/>/<see cref="TaskOutcome.Skipped"/> (resume found
    /// it already succeeded) both read as "passed"; <see cref="TaskOutcome.NeedsHuman"/>/
    /// <see cref="TaskOutcome.RateLimited"/>/<see cref="TaskOutcome.Cancelled"/> (an ambiguous,
    /// operator-actionable halt) all read as "needs-human"; everything else — a genuine action or
    /// guardrail failure, an invalid fragment, or a blocked dependency — reads as "failed".
    /// <see cref="TaskOutcome.TransientPause"/> never reaches here (never reported to
    /// <see cref="TaskFinished"/> — see its own doc comment).
    /// </summary>
    private static string SettledStatusWord(TaskOutcome outcome) => outcome switch
    {
        TaskOutcome.Succeeded => "passed",
        TaskOutcome.Skipped => "passed",
        TaskOutcome.NeedsHuman => "needs-human",
        TaskOutcome.RateLimited => "needs-human",
        TaskOutcome.Cancelled => "needs-human",
        _ => "failed", // ActionFailed, GuardrailFailed, InvalidFragment, Blocked
    };

    // --- replicated from MermaidRenderer (private there) — see class remarks, "Node-id scheme" ---

    private static IReadOnlyDictionary<string, string> AllocateNodeIdBases(IReadOnlyList<TaskNode> tasks)
    {
        List<TaskNode> ordered = tasks.OrderBy(t => t.Id, StringComparer.Ordinal).ToList();
        var bases = new Dictionary<string, string>(StringComparer.Ordinal);
        var taken = new HashSet<string>(StringComparer.Ordinal);

        foreach (TaskNode task in ordered)
        {
            string candidate = Sanitize(task.Id);
            if (!taken.Add(candidate))
            {
                int suffix = 2;
                string disambiguated;
                do
                {
                    disambiguated = $"{candidate}_{suffix}";
                    suffix++;
                }
                while (!taken.Add(disambiguated));

                candidate = disambiguated;
            }

            bases[task.Id] = candidate;
        }

        return bases;
    }

    private static string Sanitize(string id)
    {
        var sb = new StringBuilder(id.Length);
        foreach (char c in id)
        {
            bool safe = c is (>= 'a' and <= 'z') or (>= 'A' and <= 'Z') or (>= '0' and <= '9');
            sb.Append(safe ? c : '_');
        }

        return sb.ToString();
    }
}

